 applicable_protocol_archetypes=["lending (Compound fork)","CDP","vault/share token (ERC-4626)","yield aggregator","risk curator","liquid staking","basis trading"],
 static_indicators=["getCashPrior()/totalAssets() returning IERC20(x).balanceOf(address(this))","exchangeRateStored = (cash + borrows - reserves)/totalSupply","convertToAssets/pricePerShare with no internally tracked asset counter","supply caps checked at mint but not against the rate"],
 adapter_indicators=["adapter sums balanceOf across strategy/Ark/silo addresses","adapter treats a component vault's share price as authoritative","Compound-fork adapter template (cToken/vToken enumeration)"],
 runtime_state_indicators=["exchange rate materially above 1 and rising without proportional supply growth","market supply exceeding the configured supply cap","components in totalAssets whose underlying market is impaired or halted","donation-shaped Transfer events into the vault/cToken with no matching Mint"],
 cross_contract_indicators=["a counted component is itself an ERC-4626 whose rate is externally manipulable","offboarding partially complete: strategy removed from UI but still in the assets array"],
 decisive_guards=["Internally tracked totalAssets counter incremented only on accounted deposits","Rate floors/ceilings and per-block rate-change caps that revert","Virtual shares/assets offset (ERC-4626 OZ v5 style)","Explicit skim of unaccounted balance to reserves rather than to the rate","Offboarding removes the component from the assets array atomically with pausing it"],
 false_positive_killers=["totalAssets derived from an internal counter, not balanceOf (kills the pair)","Rate is monotonic and rate-limited per block","Inbound transfers to the accounting boundary are rejected or swept to a reserve"],
 local_defensive_property="On a fork, transfer an arbitrary amount of each counted asset directly into every accounting boundary; the share price, exchange rate and derived borrow power must not change.",
 evidence_strength="HIGH",
