 mandatory_preconditions=[
   "Share price computed from a multi-component totalAssets()",
   "At least one component's valuation is externally influenceable, stale, or can return an absurd value",
   "Deposit and redeem are both reachable in a short window (same tx or same block)",
   "Other depositors' value is pooled with the attacker's"],
 optional_amplifiers=["Flash loans","Offboarding in progress","Impaired upstream market (e.g. a collapsed strategy)","Zero/near-zero reported totalAssets making share minting cheap"],
 applicable_protocol_archetypes=["yield aggregator","vault/share token","risk curator","structured product","onchain capital allocator","basis trading","indexes"],
 static_indicators=["totalAssets() looping over a strategies/arks array","component valuation via an external convertToAssets or oracle without sanity bounds","no per-block deposit/redeem rate-change cap","no minimum totalAssets floor before share minting"],
 adapter_indicators=["adapter enumerates strategies/arks/silos dynamically","adapter includes addresses of upstream markets that are paused or impaired","risk-curator adapters aggregating third-party vault positions"],
