 cross_contract_indicators=["vault depends on another protocol's vault token whose rate is donation-inflatable","curator multisig can add components without timelock"],
 decisive_guards=["Per-block share-price change cap that reverts","Deposit and redeem in the same block disallowed or fee-penalised","Component valuation bounded by an independent price with deviation caps","Offboarding atomically removes the component from totalAssets","Minimum totalAssets floor and virtual-share offset"],
 false_positive_killers=["Share price rate-limited per block (kills same-transaction extraction)","Single-asset vault with no external valuation","Withdrawals queued with a delay and priced at settlement"],
 local_defensive_property="On a fork, for each component, force its valuation to zero and to 10x; the vault's mint/redeem must revert or be bounded, never transfer more than the depositor's pro-rata realisable share.",
